<?php
require_once 'includes/config.php';require_admin();$class=(int)($_GET['class_id']??0);$year=trim((string)($_GET['year']??''));$term=trim((string)($_GET['term']??''));$month=trim((string)($_GET['month']??''));$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$sid=(int)($_GET['student_id']??0);$where=[];$p=[];if($class){$where[]='r.ClassId=:c';$p[':c']=$class;}if($year!==''){$where[]='r.AcademicYear=:y';$p[':y']=$year;}if($term!==''){$where[]='r.Term=:t';$p[':t']=$term;}if($month!==''&&preg_match('/^\d{4}-\d{2}$/',$month)){$where[]="DATE_FORMAT(r.PostingDate,'%Y-%m')=:m";$p[':m']=$month;}if($from!==''){$where[]='DATE(r.PostingDate)>=:f';$p[':f']=$from;}if($to!==''){$where[]='DATE(r.PostingDate)<=:to';$p[':to']=$to;}if($sid){$where[]='r.StudentId=:s';$p[':s']=$sid;}
$select='SELECT r.id,r.StudentId,r.ClassId,r.SubjectId,r.marks,r.PostingDate,r.AcademicYear,r.Term,r.ExamType,r.Published,r.approval_state,s.StudentName,s.RollId,c.ClassName,c.Section,sub.SubjectName FROM tblresult r JOIN tblstudents s ON s.StudentId=r.StudentId LEFT JOIN tblclasses c ON c.id=r.ClassId LEFT JOIN tblsubjects sub ON sub.id=r.SubjectId';
try{$q=$dbh->prepare($select.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY r.PostingDate DESC,r.StudentId LIMIT 3000');$q->execute($p);$rows=$q->fetchAll();}catch(Throwable $e){http_response_code(500);exit('Academic archive requires Phase 1 result fields and the Phase 11 archive index. Review migrations and error logs.');}$classes=$dbh->query('SELECT id,ClassName,Section FROM tblclasses ORDER BY ClassName,Section')->fetchAll();$students=$dbh->query('SELECT StudentId,StudentName,RollId FROM tblstudents ORDER BY StudentName')->fetchAll();if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="srms-academic-archive.csv"');$o=fopen('php://output','w');fputcsv($o,['Student','Roll ID','Class','Subject','Marks','Year','Term','Exam','Date','Status']);foreach($rows as $r)fputcsv($o,[$r['StudentName'],$r['RollId'],$r['ClassName'].' '.$r['Section'],$r['SubjectName'],$r['marks'],$r['AcademicYear'],$r['Term'],$r['ExamType'],$r['PostingDate'],$r['approval_state']??'']);fclose($o);exit;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Academic Archive | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container srms-page"><p><a href="dashboard.php">← Dashboard</a> | <a href="result-history.php">Result History</a></p><h2>Historical Academic Performance Archive</h2><p>Search historical marks and examination records by class, student, academic period and date. Records are displayed as stored; this page does not modify historical results.</p><form method="get" class="panel panel-default panel-body row"><div class="col-md-3 form-group"><label>Class/Form</label><select name="class_id" class="form-control"><option value="0">All classes</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$class===(int)$c['id']?'selected':''?>><?=e($c['ClassName'].' '.$c['Section'])?></option><?php endforeach;?></select></div><div class="col-md-2 form-group"><label>Student</label><select name="student_id" class="form-control"><option value="0">All students</option><?php foreach($students as $s):?><option value="<?=$s['StudentId']?>" <?=$sid===(int)$s['StudentId']?'selected':''?>><?=e($s['StudentName'].' — '.$s['RollId'])?></option><?php endforeach;?></select></div><div class="col-md-2 form-group"><label>Academic Year</label><input name="year" value="<?=e($year)?>" class="form-control" placeholder="2026/2027"></div><div class="col-md-2 form-group"><label>Term</label><input name="term" value="<?=e($term)?>" class="form-control" placeholder="Term 1"></div><div class="col-md-2 form-group"><label>Month</label><input type="month" name="month" value="<?=e($month)?>" class="form-control"></div><div class="col-md-2 form-group"><label>Date from</label><input type="date" name="from" value="<?=e($from)?>" class="form-control"></div><div class="col-md-2 form-group"><label>Date to</label><input type="date" name="to" value="<?=e($to)?>" class="form-control"></div><div class="col-md-12"><button class="btn btn-primary">Search archive</button> <button class="btn btn-default" name="export" value="csv">Export CSV</button></div></form><p class="text-muted">Showing up to 3,000 matching result rows.</p><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Date</th><th>Student</th><th>Class</th><th>Subject</th><th>Marks</th><th>Academic Year</th><th>Term</th><th>Exam</th><th>Approval</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['PostingDate'])?></td><td><?=e($r['StudentName'].' ('.$r['RollId'].')')?></td><td><?=e(($r['ClassName']??'').' '.($r['Section']??''))?></td><td><?=e($r['SubjectName']??'')?></td><td><?=e($r['marks'])?></td><td><?=e($r['AcademicYear']??'')?></td><td><?=e($r['Term']??'')?></td><td><?=e($r['ExamType']??'')?></td><td><?=e($r['approval_state']??'Legacy')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="9">No matching historical records.</td></tr><?php endif;?></tbody></table></div></div></main></div></div></div></div></body></html>
